// Intake record guard: flags intake records a dispatcher cannot act on.
// Built for the Dispatch Kit intake schema; works for any record with these field names.
//
// Placeholder list extended with values suggested by Automelle on the n8n community forum.
const PLACEHOLDERS = new Set([
  "", "unknown", "n/a", "na", "none", "null", "tbd", "not provided", "not given",
  "test", "example", "asdf", "x", "-", "0", "?", ".",
  "john doe", "jane doe",
  "123 main st", "123 main street", "1 main st", "1 main street",
  "999 main st", "999 main street",
  "01/01/2000", "2000-01-01", "01/01/1900", "1900-01-01",
]);
// Phone numbers are compared by their last ten digits, so "+1 (555) 555-5555" is caught too.
const FAKE_PHONES = new Set(["5555555555", "1234567890", "0123456789", "9876543210"]);
const URGENCY = ["emergency", "same_day", "routine"];

// A field counts only if a dispatcher could act on it. Nulls, blanks and
// placeholders like "unknown" or "123 Main St" do not count.
function captured(v) {
  if (v === null || v === undefined) return false;
  if (typeof v === "string") return !PLACEHOLDERS.has(v.trim().toLowerCase());
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === "object") return Object.values(v).some(captured);
  return true;
}

function digits(v) {
  return (typeof v === "string" || typeof v === "number") ? String(v).replace(/\D/g, "") : "";
}

// A phone number counts if it has at least ten digits and isn't a well-known fake,
// one digit repeated (000-000-0000), or in 555-0100 to 555-0199, the range the US
// numbering plan reserves for fiction and a model's favourite place to invent a number.
function usablePhone(v) {
  if (!captured(v)) return false;
  const d = digits(v);
  if (d.length < 10) return false;
  const last10 = d.slice(-10);
  if (FAKE_PHONES.has(last10)) return false;
  if (/^(\d)\1{9}$/.test(last10)) return false;
  if (/^\d{3}55501\d{2}$/.test(last10)) return false;
  return true;
}

function address(a) {
  if (!a || typeof a !== "object") return "(none)";
  const parts = [a.street, a.unit, a.city, a.state, a.postal_code].filter(captured);
  return parts.length ? parts.join(", ") : "(none)";
}

return $input.all().map((item) => {
  // Accept the record as the whole request body, or wrapped as { "record": { ... } }.
  const body = item.json.body ?? item.json;
  const r = (body && body.record) ? body.record : (body || {});
  const problems = [];

  // Optional: the number the caller actually called from. Send it next to the record as
  // { "record": { ... }, "caller_id": "+15551234567" }, or as ?caller_id= on the webhook URL,
  // or in an x-caller-id header. The record itself has no field for it: the agent never sees
  // caller ID, which is exactly why it can be used to check the agent.
  const callerId =
    (body && body.caller_id) ??
    (item.json.query && item.json.query.caller_id) ??
    (item.json.headers && item.json.headers["x-caller-id"]) ??
    null;

  if (r.schema_version === undefined) {
    problems.push("no schema_version, so this may not be an intake record at all");
  }
  if (!URGENCY.includes(r.urgency)) {
    problems.push(`urgency is ${JSON.stringify(r.urgency)}, expected one of: ${URGENCY.join(", ")}`);
  }
  const reachable = usablePhone(r.callback_number);
  const locatable = captured(r.service_address);
  if (!reachable) problems.push("no usable callback_number");
  if (!locatable) problems.push("no usable service_address");
  if (!captured(r.problem_summary)) problems.push("no problem_summary");

  // A callback number that differs from caller ID is not wrong on its own: people call from
  // work and ask to be called back at home. But a hallucinated number looks exactly like a
  // real one and passes every placeholder check, so a human should look at the difference.
  const idDigits = digits(callerId).slice(-10);
  const callbackDiffers =
    reachable && idDigits.length === 10 && digits(r.callback_number).slice(-10) !== idDigits;
  if (callbackDiffers) {
    problems.push(`callback_number differs from caller ID ${callerId}; confirm the agent didn't invent it`);
  }

  const emergency = r.urgency === "emergency";
  const unreachable = emergency && (!reachable || !locatable);

  // Every emergency reaches a human now. An emergency nobody can act on is the worst case.
  let severity = "ok";
  if (emergency) severity = "page";
  else if (problems.length) severity = "review";

  const summary = captured(r.problem_summary) ? r.problem_summary : "(no summary)";
  const idNote = callbackDiffers ? ` Caller ID was ${callerId}, not the logged number.` : "";
  let alert_text;
  if (unreachable) {
    const fallback = digits(callerId).length >= 10
      ? `Caller ID was ${callerId}: call that back now.`
      : "Pull the caller ID from your phone platform and call back now.";
    alert_text =
      `[PAGE] EMERGENCY (${r.emergency_type || "type not set"}) with no way to act on it. ` +
      `Missing: ${[!reachable && "callback number", !locatable && "address"].filter(Boolean).join(" and ")}. ` +
      `${fallback} Summary: ${summary}`;
  } else if (emergency) {
    alert_text =
      `[PAGE] Emergency (${r.emergency_type || "type not set"}) at ${address(r.service_address)}. ` +
      `Call back: ${r.callback_number}.${idNote} Summary: ${summary}`;
  } else if (severity === "review") {
    alert_text = `[REVIEW] Intake record needs a human: ${problems.join("; ")}. Summary: ${summary}`;
  } else {
    alert_text = "";
  }

  return { json: { severity, unreachable, problems, alert_text, caller_id: callerId, record: r } };
});
